import { useEffect, useState } from "react";

export function TicketDetails({ ticketId }: { ticketId: string }) {
  const [ticket, setTicket] = useState<Ticket | null>(null);

  useEffect(() => {
    // Whichever response arrives last wins
    fetch(`/api/tickets/${ticketId}`)
      .then((res) => res.json() as Promise<Ticket>)
      .then(setTicket)
      .catch(showError);
  }, [ticketId]);

  return ticket ? <TicketView ticket={ticket} /> : <Spinner />;
}

import { useEffect, useState } from "react";

export function TicketDetails({ ticketId }: { ticketId: string }) {
  const [ticket, setTicket] = useState<Ticket | null>(null);

  useEffect(() => {
    const controller = new AbortController();
    const { signal } = controller;
    fetch(`/api/tickets/${ticketId}`, { signal })
      .then((res) => res.json() as Promise<Ticket>)
      .then((data) => {
        if (!signal.aborted) setTicket(data); // only the current run
      })
      .catch((err: unknown) => {
        if (!signal.aborted) showError(err); // AbortError is expected
      });
    return () => controller.abort(); // before the next ticket's fetch
  }, [ticketId]);

  return ticket ? <TicketView ticket={ticket} /> : <Spinner />;
}
